        elif y < 0:
            dy = 1
        else:
            dy = 0
        # clamp implicit
        return [dx, dy]

    # Pursuit/evade heuristics
    # If an opponent is nearby flagged
    opp_dirs = []
    opp_senses = get(observation, "opponent_senses", {})
    for dx_i in (-1, 0, 1):
