        dx_raw, dy_raw = opp_dirs[0]
        dx = -dx_raw
        dy = -dy_raw

        # clamp to allowed
        if dx not in (-1, 0, 1): dx = 0
        if dy not in (-1, 0, 1): dy = 0
        return [dx, dy]

    # Default: stay or minor exploration
    # If near boundary hints exist, push inward
    if grid is not None:
        max_x = get(grid, "width", 0)
        max_y = get(grid, "height", 0)
        if max_x:
